function firstLoneLetter(s: string): number {
  for (let i = 0; i < s.length; i++) {
    let seen = 0;
    for (let j = 0; j < s.length; j++) if (s[j] === s[i]) seen++;
    if (seen === 1) return i;
  }
  return -1;
}

